result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "bs.py", "content": """"Black-Scholes pricer (no dividends) with implied volatility by bisection."""

import math


def _norm_cdf(x: float) -> float:
    """Standard normal CDF via math.erf."""
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def _d1_d2(S: float, K: float, r: float, sigma: float, T: float):
    sqrtT = math.sqrt(T)
    d1 = (math.log(S / K) + (r + 0.5 * sigma * sigma) * T) / (sigma * sqrtT)
    d2 = d1 - sigma * sqrtT
    return d1, d2


def call_price(S: float, K: float, r: float, sigma: float, T: float) -> float:
    """Black-Scholes European call price."""
    if T == 0.0 or sigma == 0.0:
        return max(S - K * math.exp(-r * T), 0.0)
    d1, d2 = _d1_d2(S, K, r, sigma, T)
    return S * _norm_cdf(d1) - K * math.exp(-r * T) * _norm_cdf(d2)


def put_price(S: float, K: float, r: float, sigma: float, T: float) -> float:
    """Black-Scholes European put price."""
    if T == 0.0 or sigma == 0.0:
        return max(K * math.exp(-r * T) - S, 0.0)
    d1, d2 = _d1_d2(S, K, r, sigma, T)
    return K * math.exp(-r * T) * _norm_cdf(-d2) - S * _norm_cdf(-d1)


def implied_vol(price: float, S: float, K: float, r: float, T: float,
                lo: float = 1e-6, hi: float = 5.0,
                tol: float = 1e-12, max_iter: int = 200) -> float:
    """Implied volatility of a European call via bisection on [lo, hi]."""
    f = lambda s: call_price(S, K, r, s, T) - price
    flo, fhi = f(lo), f(hi)
    if flo > 0.0:
        raise ValueError("price below intrinsic value (vol below lower bound)")
    if fhi < 0.0:
        raise ValueError("price above upper bound for vol in [1e-6, 5.0]")
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        fm = f(mid)
        if abs(fm) < tol or (hi - lo) < tol:
            return mid
        if fm < 0.0:
            lo, flo = mid, fm
        else:
            hi, fhi = mid, fm
    return 0.5 * (lo + hi)
